const { PrismaClient } = require('@prisma/client');
const express = require('express');

const basePrisma = new PrismaClient();

const app = express();
app.use(express.json());

// Middleware to create a tenant-scoped Prisma client
app.use((req, res, next) => {
  const tenantId = req.headers['x-tenant-id'];

  if (!tenantId) {
    return res.status(400).json({ error: 'x-tenant-id header is required' });
  }

  // Extend the Prisma client for this request
  req.prisma = basePrisma.$extends({
    query: {
      item: {
        async findMany({ args, query }) {
          args.where = { ...args.where, tenantId };
          return query(args);
        },
        async create({ args, query }) {
          args.data = { ...args.data, tenantId };
          return query(args);
        }
      }
    }
  });

  next();
});

app.get('/items', async (req, res) => {
  try {
    const items = await req.prisma.item.findMany();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

app.post('/items', async (req, res) => {
  const { name } = req.body;
  if (!name) {
    return res.status(400).json({ error: 'name is required' });
  }

  try {
    const item = await req.prisma.item.create({
      data: { name }
    });
    res.json(item);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

